// Narrow timing driver for the pinned aSCED C++ BP4 decoder.
// Input is generated by benchmark_bp_kernels.py; graph setup is untimed.
#include "Decoder_Factory.h"
#include <chrono>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>

int main(int argc, char** argv) {
    if (argc != 2) return 2;
    std::ifstream in(argv[1]);
    size_t m, n, shots, cap;
    double p;
    if (!(in >> m >> n >> shots >> cap >> p)) throw std::runtime_error("bad workload header");
    matrix H(m, vector(n));
    std::vector<vector> syndromes(shots, vector(m));
    unsigned value;
    for (auto& row : H) for (auto& item : row) { in >> value; item = static_cast<uint8_t>(value); }
    for (auto& row : syndromes) for (auto& item : row) { in >> value; item = static_cast<uint8_t>(value); }
    if (!in) throw std::runtime_error("truncated workload");
    auto config = std::make_shared<BP_Decoder_Config>(H, "GF4");
    config->max_iterations = cap;
    config->cn_processing_type = "SPA";
    config->scheduling_type = "Parallel";
    auto decoder = create_decoder(config);
    auto* bp = dynamic_cast<BP_Decoder*>(decoder.get());
    if (!bp) throw std::runtime_error("no BP4 decoder");
    bp->get_epsilon(p);
    std::cout << "{\"timings\":{\"early\":[";
    for (int mode = 0; mode < 2; ++mode) {
        if (mode) std::cout << "],\"fixed8\":[";
        bp->early_stopping = mode == 0;
        for (int repeat = 0; repeat < 3; ++repeat) {
            bp->syndrome = syndromes[0]; bp->decode();
            std::vector<unsigned> iterations, success;
            std::vector<vector> candidates;
            unsigned long long checksum = 0;
            auto start = std::chrono::steady_clock::now();
            for (const auto& s : syndromes) {
                bp->syndrome = s;
                bp->decode();
                iterations.push_back(static_cast<unsigned>(bp->iteration));
                success.push_back(bp->syndromes_match ? 1U : 0U);
                if (repeat == 0) candidates.push_back(bp->error_estimate);
                for (auto x : bp->error_estimate) checksum = checksum * 131 + x;
            }
            auto end = std::chrono::steady_clock::now();
            auto ns = std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count();
            if (repeat) std::cout << ',';
            std::cout << "{\"ns_per_shot\":" << (double)ns/shots << ",\"iterations\":[";
            for (size_t i=0;i<shots;++i) { if(i)std::cout<<',';std::cout<<iterations[i]; }
            std::cout << "],\"success\":[";
            for (size_t i=0;i<shots;++i) { if(i)std::cout<<',';std::cout<<success[i]; }
            std::cout << "],\"candidate_checksum\":" << checksum;
            if (repeat == 0) {
                std::cout << ",\"candidates_native_ixzy\":[";
                for (size_t i=0;i<candidates.size();++i) {
                    if(i)std::cout<<',';
                    std::cout << '"';
                    for (auto x : candidates[i]) std::cout << static_cast<unsigned>(x);
                    std::cout << '"';
                }
                std::cout << ']';
            }
            std::cout << '}';
        }
    }
    std::cout << "]}}\n";
}
